import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Plan 0017 — abstraction as a legal move","description":"","frontmatter":{"title":"Plan 0017 — abstraction as a legal move","type":"plan","date":"2026-10-14T00:00:00.000Z","status_note":"starting.  Implements ADR 0004 — the unit of invention is a\\nconstructed *object*, declared as serializable data and admitted by\\nthe adversarial referee, never a minted rewrite the policy hands to\\na trusted seam."},"headers":[],"relativePath":"graphopt/project/plans/0017-abstraction-as-move.md","filePath":"vendored/graphopt/project/plans/0017-abstraction-as-move.md"}`),a={name:`graphopt/project/plans/0017-abstraction-as-move.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plan-0017-—-abstraction-as-a-legal-move" tabindex="-1">Plan 0017 — abstraction as a legal move <a class="header-anchor" href="#plan-0017-—-abstraction-as-a-legal-move" aria-label="Permalink to “Plan 0017 — abstraction as a legal move”">​</a></h1><h2 id="stages" tabindex="-1">Stages <a class="header-anchor" href="#stages" aria-label="Permalink to “Stages”">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>What</th><th>Depends on</th></tr></thead><tbody><tr><td>0</td><td><code>derive=</code> toward data — extend <code>dspec</code> to cover the remaining procedural derives (&quot;pull dim from tuple&quot;, attr arithmetic); count the serializable total</td><td><code>laws/cond.py</code>, <code>dspec</code> machinery</td></tr><tr><td>1</td><td><strong>The object record</strong> — generalize <code>lemmas</code>/<code>law_to_data</code>/<code>law_from_data</code> into a declared-object record (pattern + cond + derive + tags + cert) so a stored <em>abstraction</em> reconstructs into a live, firing object the same way <code>--admit</code> reconstructs a stored lemma</td><td><code>laws/serialize.py</code>, <code>evidence.py</code></td></tr><tr><td>2</td><td><strong>The guide seam</strong> — <code>meta_game</code>&#39;s real role: the policy chooses <em>which generator invests compute where</em> (census/vocab/oracle/generator passes), not which rewrite to fire. Wire the action space to the generator inventory; measure against the enumeration baseline</td><td><code>meta_game.py</code>, <code>pipeline.py</code></td></tr><tr><td>3</td><td><strong>Adversarial admission for synthesized objects</strong> — a stored object passes numeric oracle → view oracle → typed-pay gate → cert replay before it&#39;s usable; precondition must exist as a <code>cond</code> (the <code>w:v_commutes_view</code>/<code>id:same_pairing</code> gaps are the standing <code>cond</code> work)</td><td>stage 1, the oracles</td></tr></tbody></table><h2 id="honest-boundaries-carried-in" tabindex="-1">Honest boundaries carried in <a class="header-anchor" href="#honest-boundaries-carried-in" aria-label="Permalink to “Honest boundaries carried in”">​</a></h2><ul><li>A synthesized abstraction whose <code>cond</code> can&#39;t be written declaratively is not admissible as data — it goes through the same Python-hook review path as a hand-written law. No side-door.</li><li><code>derive=</code>-as-data is bounded — attribute arithmetic beyond the DSL stays procedural; the serializable total is reported honestly, not forced.</li><li>The verifier stays the authority at every stage: RL guides generator investment, never mints semantics (ADR 0002 Rule 3).</li></ul><h2 id="exit-criteria" tabindex="-1">Exit criteria <a class="header-anchor" href="#exit-criteria" aria-label="Permalink to “Exit criteria”">​</a></h2><p>A stored, serializable <em>introduced object</em> — declared as data — that the pipeline admits through the adversarial gauntlet and that fires identically to its declared semantics, with a replayable certificate. The first candidate is an object the machinery already understands (a carrier-style abstraction or a conditional view law from the oracle&#39;s guard table), not a novel one — the seam is what&#39;s new, not the object.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};